(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/glyphs-0028.js"] = [{"id":"glyph-seal-88f9","script":"seal","character":"裹","reading":"guǒ","description":"guǒ：(1)包；缠绕～脚。把这包糖～好。～足不前。\n(2)夹带；夹杂不该把次货～进去卖∶人坏人～在一起一时分不清。\n(3)方言，吸（奶）小孩生下来就会～奶。奶头被这孩子～得生疼。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-裹"},{"id":"glyph-seal-88fe","script":"seal","character":"裾","reading":"jū；jv","description":"jū：(1)衣服的大襟。\n(2)衣服的前后部分。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-裾"},{"id":"glyph-seal-890a","script":"seal","character":"褊","reading":"biǎn","description":"biǎn：(1)衣服狭小。\n(2)狭小，狭隘～小。～急。～狭（狭小，如土地～～”，气量～～”）。～窄。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-褊"},{"id":"glyph-seal-8910","script":"seal","character":"褐","reading":"hè","description":"hè：(1)粗布或粗布衣服短～。\n(2)黑黄色～煤（煤的一种，多为褐色，除可作燃料外，还可以提炼汽油、煤油、焦油等。亦称褐炭”）。～藻（藻类植物的一大类，褐色，是海底最主要的藻类，富含碘质和胶质，海带就是供食用的褐藻）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-褐"},{"id":"glyph-seal-8912","script":"seal","character":"褒","reading":"bāo；bǎo","description":"bǎo：(1)赞扬，夸奖，与贬”相对～奖。～扬。～贬。～义词。\n(2)衣襟宽大～衣博带。\n(3)中国周代诸侯国名，在今陕西省勉县东南。亦称有褒”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-褒"},{"id":"glyph-seal-8913","script":"seal","character":"褓","reading":"bǎo","description":"bǎo：〔襁～〕见襁”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-褓"},{"id":"glyph-seal-891a","script":"seal","character":"褚","reading":"chǔ；zhǔ","description":"zhǔ：(1)用丝绵装衣服。\n(2)囊袋。\n(3)古同储”，贮藏。\n(4)古代覆盖棺材的红布～幕。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-褚"},{"id":"glyph-seal-891b","script":"seal","character":"褛","reading":"lǚ","description":"用于“褴褛”，形容衣服破烂。","enabled":true,"collection":"篆字扩展","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-892b","script":"seal","character":"褫","reading":"chǐ","description":"chǐ：(1)剥夺～夺（依法剥夺）。～革（革除，剥夺）。～职（革职）。～魄（使人失魂落魄）。\n(2)脱去，解下解佩而～绅。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-褫"},{"id":"glyph-seal-8930","script":"seal","character":"褰","reading":"qiān","description":"qiān：(1)揭起子惠思我，～裳涉溱”。\n(2)古代称套裤。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-褰"},{"id":"glyph-seal-8934","script":"seal","character":"褴","reading":"lán","description":"楚谓无缘之衣谓之褴,紩衣谓之褛。\n泛指服饰破烂\n褴褛\n一个个面黄肌瘦,","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-褴"},{"id":"glyph-seal-8941","script":"seal","character":"襁","reading":"qiǎng","description":"qiǎng：〔～褓〕包婴儿的被、毯等，如在～～中”（婴儿时代）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-襁"},{"id":"glyph-seal-8944","script":"seal","character":"襄","reading":"xiāng","description":"xiāng：(1)帮助，辅佐～办。～理。～助。～赞（赞助）。\n(2)完成，相助而成葬定公，雨，不克～事”。\n(3)冲上～陵。\n(4)上举，昂起臣闻交龙～首奋翼”。\n(5)高～岸夷涂。”\n(6)古同攘”，扫除。\n(7)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-襄"},{"id":"glyph-seal-895e","script":"seal","character":"襞","reading":"bì","description":"bì：(1)衣服和肠、胃等内部器官上的褶子皱～。胃～。\n(2)摺叠衣裙。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-襞"},{"id":"glyph-seal-8966","script":"seal","character":"襦","reading":"rú","description":"rú：(1)短衣，短袄珠～。绣腰～。\n(2)幼儿的围嘴儿。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-襦"},{"id":"glyph-seal-897f","script":"seal","character":"西","reading":"xī","description":"xī：(1)方向，太阳落下的一边，与东”相对～面。～晒。～域。～方。～席（旧时对幕友或家塾教师的敬称。古代主位在东，宾位在西。亦称西宾”）。～宫（借指妃嫔）。\n(2)事物的样式或方法属于西方的（多指欧美各国）～学。～画。～餐。～医。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-西"},{"id":"glyph-seal-8981","script":"seal","character":"要","reading":"yào；yāo","description":"yào：(1)索取～账。～价。\n(2)希望，想～强。～好。\n(3)请求她～我给她读报。\n(4)重大，值得重视的重～。～人。～领。纲～。～言不烦。\n(5)应该，必须须～。\n(6)将（jiāng）将～。快～。\n(7)如果，倘若～是。\n(8)表选择～么。～不。～不然。\nyāo：(1)求，有所倚仗而强求～求。～挟。\n(2)古同腰”。\n(3)古同邀”，中途拦截。\n(4)古同邀”，约请。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-要"},{"id":"glyph-seal-8983","script":"seal","character":"覃","reading":"tán；qín","description":"tán：(1)深广～思。\n(2)延长，延及～恩。\n(3)姓。\nqín：姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-覃"},{"id":"glyph-seal-8986","script":"seal","character":"覆","reading":"fù","description":"fù：(1)遮盖，蒙～盖。～溺。～蔽。～被（遮盖，喻恩荫）。～庇。\n(2)翻，倾倒，败，灭～舟。颠～。～灭。～辙（翻过车的道路，喻曾经失败的做法）。～没（mò）。～水难收。～巢无完卵（喻灭门之祸，无一得免，亦喻整体覆灭，个人不能幸存）。前车之～，后车之鉴。\n(3)同复”①②。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-覆"},{"id":"glyph-seal-89c1","script":"seal","character":"见","reading":"jiàn","description":"歧王宅里寻常见\n⒈看到看～。耳闻目～。〈引〉接触，遇到胶卷忌讳～光。病刚好，不要～寒。\n⒉看得出，显现出初～成效。已～分晓。\n⒊会面，会晤会～。接～。\n⒋看法，认识，扩大知识～解。～识。远～。不固执己～。\n⒌指明出处～上页。\n⒍助词。\n①用在动词前，〈表〉被动莫～笑。别～怪。\n②用在动词前，〈表〉对说话人怎么样～教。请～谅。\n⒎用在\"听\"、\"闻\"、\"看\"等动词后，〈表〉效果听～了。看～了。\n⒏［见习］学得专业知识的人刚到工作岗位去，现场实地工作实习～习生。\n⒐［见证］亲眼看到，可以作证的人。也指可以作证的事物。\n⒈显出，出现，显露表～。华佗再～。昙花一～。\n见\"儋藍\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-见"},{"id":"glyph-seal-89c2","script":"seal","character":"观","reading":"guān","description":"⒈看～看。～赏。登楼～望。袖手旁～。\n⒉对事物的认识或看法世界～。正确的～点。她很乐～。\n⒊看到的景物和景象美～。奇～。\n⒉楼台之类台～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-观"},{"id":"glyph-seal-89c4","script":"seal","character":"规","reading":"guī","description":"法度、准则\n必将\n⒈画圆形的工具圆～。两脚～。\n⒉法则，章程，惯例～则。～章。常～办理。革除陋～。\n⒊劝告，告诫～劝。～谏。\n⒋谋划，制定，决定～划。～定。\n①俗成或规定的标准广告应该～范化。\n②合乎一定的标准课本语文，必须～范化。\n①画圆形与方形的两种工具。\n②规章制度循～蹈矩。\n③行为端正老实～ ～矩矩。\n规guì 1.见\"规规\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-规"},{"id":"glyph-seal-89c6","script":"seal","character":"视","reading":"shì","description":"⒈看～力。～若无睹。\n⒉看待，看作轻～。～如寇仇。～少如长。\n⒊观察，察看～察。巡～。\n⒋活，生存长生久～。\n①眼睛与所看目标之间的假想直线。\n②眼睛所能看到的。〈喻〉注意的方向或目标她的话是在转移大家的～线。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-视"},{"id":"glyph-seal-89c7","script":"seal","character":"觇","reading":"chān","description":"窥探,侦察\n觇标\n⒈偷看，侦察～望。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-觇"},{"id":"glyph-seal-89c8","script":"seal","character":"览","reading":"lǎn","description":"观赏\n览làn 1.唐代南诏副将官职名。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-览"},{"id":"glyph-seal-89c9","script":"seal","character":"觉","reading":"jué；jiào","description":"jué：感觉、察觉；醒悟。jiào：睡眠，如睡觉、午觉。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-89ca","script":"seal","character":"觊","reading":"jì","description":"觊觎\n⒈企图，期望以～其利。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-觊"},{"id":"glyph-seal-89cb","script":"seal","character":"觋","reading":"xí","description":"觋xí搞迷信活动，骗人钱财的男巫。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-觋"},{"id":"glyph-seal-89ce","script":"seal","character":"觎","reading":"yú","description":"非分的希望","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-觎"},{"id":"glyph-seal-89cf","script":"seal","character":"觏","reading":"gòu","description":"遭遇\n构成。通构”\n⒈遇，遭遇，遇见～疾。相～≤少～到。\n⒉看见登高楼～平川。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-觏"},{"id":"glyph-seal-89d0","script":"seal","character":"觐","reading":"jìn","description":"朝见\n诸侯秋季朝见天子或朝拜圣地\n泛指诸侯朝见天子\n觐jìn朝见君主或拜谒圣地～见。朝～。拜～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-觐"},{"id":"glyph-seal-89d2","script":"seal","character":"角","reading":"jiǎo；jué","description":"jiǎo：(1)牛、羊、鹿等头上长出的坚硬的东西牛～。鹿～。犄～。～质。\n(2)形状像角的菱～。皂～。\n(3)突入海中的尖形的陆地（多用于地名）成山～（在中国山东省）。\n(4)几何学指从一点引出两条直线所夹成的平面部分直～。～度。～钢。～尺。\n(5)物体边沿相接的地方～落。\n(6)额骨（俗称额角”）。\n(7)古代未成年男孩头顶两侧束发为髻（亦称总角”）。\n(8)古代军中的一种乐器画～∨～。\n(9)古代量器，酒的计量单位先取两～酒来”。\n(10)中国货币单位。\n(11)星名，二十八宿之一。\n(12)量词。\njué：(1)古代酒器，青铜制，形似爵而无柱，两尾对称，有盖，用以温酒和盛酒。\n(2)演员，或指演员在戏剧中所扮演的人物～色。名～。\n(3)较量，竞争～力。～斗。～逐。\n(4)古代五音之一，相当于简谱3”。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-角"},{"id":"glyph-seal-89da","script":"seal","character":"觚","reading":"gū","description":"gū：(1)古代酒器，青铜制，盛行于中国商代和西周初期，喇叭形口，细腰，高圈足。\n(2)古代用来书写的木简操～。\n(3)棱角甘泉泰??（shì）紫坛，八～宣通象八方”。\n(4)剑柄操其～，招其末”。\n(5)古同弧”，独立不群。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-觚"},{"id":"glyph-seal-89de","script":"seal","character":"觞","reading":"shāng","description":"向人敬酒","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-觞"},{"id":"glyph-seal-89e3","script":"seal","character":"解","reading":"jiě；jiè；xiè","description":"jiě：(1)剖开，分开～剖。分～。瓦～。～体。\n(2)把束缚着、系着的东西打开～开。～甲归田。～囊相助。\n(3)除去，除，废除，停止～放（ａ．使广大人民群众脱离压迫；ｂ．解除束缚而得到自由）。～除。～饿。～乏。～惑。～疑。～围。～脱。～雇。～聘。～散。～毒。\n(4)溶化溶～。～冻。\n(5)讲明白，分析说明～释。～析。～说。劝～。～嘲。\n(6)懂，明白理～。见～。\n(7)调和，处理～决⊥～。调（tiáo）～。排～。\n(8)高兴，开心～颜而笑。\n(9)排泄～手。\n(10)代数方程中未知数的值。\n(11)演算方程式～方程。\n(12)文体的一种，如韩愈《进学解》。\n系；结；\njiè：(1)发送。\n(2)押送财物或犯人押～。起～。～差（chāi）。～回北京。\n系；结；\nxiè：(1)古同懈”，松弛，懈怠。\n(2)古同邂”，邂逅。\n(3)旧时指杂技表演的各种技艺，特指骑在马上表演的技艺卖～的。跑马卖～。\n(4)姓。\n〔～湖〕湖名，在中国山西省。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-解"},{"id":"glyph-seal-89e5","script":"seal","character":"觥","reading":"gōng","description":"gōng：(1)古代酒器，腹椭圆，上有提梁，底有圈足，兽头形盖，亦有整个酒器作兽形的，并附有小勺～筹交错（酒器和酒筹交互错杂，形容宴饮尽欢）。\n(2)大，丰盛～羊（大羊）。～船。～饭。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-觥"},{"id":"glyph-seal-89e6","script":"seal","character":"触","reading":"chù","description":"用角抵人或物\n撞,碰\n接触\n遇到;遭受\n①接触；碰～电、一～即发。\n②触动；感动；感～、忽有所～。\n【触机】触动灵机不假思索～即发。\n【触角】〈生〉通常指动物头部细长的感觉器官。在节肢动物中由附肢变成。具触觉、嗅觉功能。有的种类还具其他多种功能。\n【触景生情】为眼前的景物所触动而产生某种情感。\n【触觉】〈生〉机械刺激引起的皮肤感觉。狭义指刺激轻轻接触皮肤所引起的肤觉。广义还包括压觉和振动觉。盲聋哑人的触觉多有高度的发展，以补偿听觉和视觉缺陷。\n【触类旁通】掌握某种知识或规律后，推知相关的知识或规律。旁通互相贯通。\n【触目惊心】见【怵目惊心】。\n【触目伤怀】看到某种事物而引起内心伤感。\n【触手】〈生〉无脊椎动物头部细长柔韧的突起物。主要作触觉和卷攫用，间或也有呼吸、运动、支持身体等功能。水螅、沙蚕、海参等都具触手。\n⒈抵，用角顶撞有角者～。\n⒉碰撞，碰着～动。～礁。～电。接～。～目惊心。\n⒊冒犯～犯。～怒。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-触"},{"id":"glyph-seal-89ef","script":"seal","character":"觯","reading":"zhì","description":"古时饮酒用的器皿。青铜制。形似尊而小,或有盖","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-觯"},{"id":"glyph-seal-89f3","script":"seal","character":"觳","reading":"hú","description":"hú：〔～觫〕恐惧颤抖的样子。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-觳"},{"id":"glyph-seal-8a00","script":"seal","character":"言","reading":"yán","description":"yán：(1)讲，说～说。～喻。～道。～欢。～情。～必有中（zhòng）（一说就说到点子上）。\n(2)说的话～论。～辞（亦作言词”）。语～。～语。～简意赅。\n(3)汉语的字五～诗。七～绝句。洋洋万～。\n(4)语助词，无义～归于好。～告师氏，～告～归”。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-言"},{"id":"glyph-seal-8a07","script":"seal","character":"訇","reading":"hōng","description":"hōng：形容大声～的一声。\n〔阿～〕伊斯兰教主持教仪、讲授经典的人。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-訇"},{"id":"glyph-seal-8a1a","script":"seal","character":"訚","reading":"yín","description":"⒈和悦而正直地争辩。\n⒉谦和而恭敬的样子。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-訚"},{"id":"glyph-seal-8a3e","script":"seal","character":"訾","reading":"zī","description":"zī：(1)钱财～算。\n(2)估量，限度～粟而税”。\n(3)希求不～重器”。\n(4)古同咨”，嗟叹声。\n(5)古同恣”，恣纵，狂放。\n(6)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-訾"},{"id":"glyph-seal-8a48","script":"seal","character":"詈","reading":"lì","description":"lì：骂，责骂乃使勇士往～齐王”。～言。～骂。～辱。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-詈"},{"id":"glyph-seal-8a79","script":"seal","character":"詹","reading":"zhān","description":"zhān：(1)说话烦琐，喋喋不休的样子大言炎炎，小言～～”。\n(2)至五日为期，六日不～”。\n(3)姓。\n〔～事〕古代官名，掌皇后太子家事。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-詹"},{"id":"glyph-seal-8a89","script":"seal","character":"誉","reading":"yù","description":"通举”。推荐\n荣誉,美名\n⒈名声名～。声～。荣～。\n⒉特指好的名声～满全球。\n⒊赞扬，赞美称～。～不绝口。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-誉"},{"id":"glyph-seal-8a8a","script":"seal","character":"誊","reading":"téng","description":"照原稿抄写清楚","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-誊"},{"id":"glyph-seal-8a93","script":"seal","character":"誓","reading":"shì","description":"shì：(1)当众或共同表示决心，依照说的话实行～师。～词。～愿。～死。\n(2)表示决心的话发～。宣～。立～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-誓"},{"id":"glyph-seal-8b66","script":"seal","character":"警","reading":"jǐng","description":"jǐng：(1)注意可能发生的危险，戒备，告诫～卫。～世。～告。～戒。～备。～惕。～省（xǐng）（警惕醒悟）。\n(2)需要戒备的事件或消息～号。～报。～钟。\n(3)感觉敏锐，见解独到～句。～觉（jué）。机～。\n(4)国家维持社会秩序和治安的武装力量～察。～士。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-警"},{"id":"glyph-seal-8b6c","script":"seal","character":"譬","reading":"pì","description":"pì：(1)打比方～如。～犹。～若。～语。～喻（比喻）。\n(2)领悟。\n(3)晓谕～解。～说（晓示述说）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-譬"},{"id":"glyph-seal-8ba1","script":"seal","character":"计","reading":"jì","description":"⒈算，算帐，核算～算。共～。～日程功。\n⒉测量或检算度数、时间等的仪表温度～。记时～。\n⒊谋略，策略～谋。～策。～巧。妙～。奇～。\n⒋谋划，盘算～划。～出万全。父母之爱子，则为之～深远。\n①争论，较量跟他～较，没意思。\n②盘算，比较她从不～较个人得失。\n③商量，打算他们～较了半天，也没结果。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-计"},{"id":"glyph-seal-8ba2","script":"seal","character":"订","reading":"dìng","description":"改正,修正\n达成协议订立;使生效\n预先约定\n把零散的纸张、书页加工成本\n②约定～报。\n③修改；改正～正、校～。\n④用线、铁丝等把书页等连在一起装～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-订"},{"id":"glyph-seal-8ba5","script":"seal","character":"讥","reading":"jī","description":"讽刺、挖苦，如讥笑、讥讽；也指规劝。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-8ba6","script":"seal","character":"讦","reading":"jié","description":"讦jié攻击或揭发别人的短处攻～。知而～之。\n讦jì 1.直言无讳。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-讦"},{"id":"glyph-seal-8ba7","script":"seal","character":"讧","reading":"hòng","description":"争扰\n讧hòng争吵，混乱内～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-讧"},{"id":"glyph-seal-8ba8","script":"seal","character":"讨","reading":"tǎo","description":"讨伐;诛戮\n⒈征伐，发动攻击～伐。征～。声～。\n⒉查究，整治检～。～军纪。\n⒊探求，研究探～。研～。\n⒋索取～债。～价还价。\n⒌求，请求，乞求～饶。～教。～饭。\n⒍招惹，引起～人厌恶。自～苦吃。～人喜欢。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-讨"},{"id":"glyph-seal-8ba9","script":"seal","character":"让","reading":"ràng","description":"退让;谦让\n允恭\n⒈不争，尽给旁人谦～。辞～。退～。〈引〉请把客人～进屋里来。特指让位、让权～贤。\n⒉将东西转给别人转～。廉价出～。\n⒊叫，许，使，任凭～他试试。～她去做。决不～国家财产受损失。～他们提意见。\n⒋被这本书～他弄坏了。泥土～雨水冲走了。\n⒌责备，责怪诮～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-让"},{"id":"glyph-seal-8baa","script":"seal","character":"讪","reading":"shàn","description":"讥刺,挖苦\n⒈讥笑，诽谤～笑。～言。\n⒉难为情，不好意思的样子搭～。她～～地回家了。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-讪"},{"id":"glyph-seal-8bab","script":"seal","character":"讫","reading":"qì","description":"⒈终了，完毕验～。收～。\n⒉终点，截止起～。\n⒊〈古〉通\"迄\"。到。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-讫"},{"id":"glyph-seal-8bad","script":"seal","character":"训","reading":"xùn","description":"解说,注释。用通俗的话解释词语的意义\n但世人未之深亮训\n⒈教导，教诲～导。～练。吸取教～。\n⒉法则，规范，准则遗～。不足为～。\n⒊申斥～人。～诫。\n⒋词义解释～释。～诂。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-训"},{"id":"glyph-seal-8bae","script":"seal","character":"议","reading":"yì","description":"评议是非\n选择\n议处;议罪\n⒈意见，言论，主张提～。异～。建～。\n⒉商量，讨论商～。～论。～定。～决。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-议"},{"id":"glyph-seal-8baf","script":"seal","character":"讯","reading":"xùn","description":"木讯\n⒈问，询问，特指审问～问。传～。审～。\n⒉音信，消息音～。通～。新华社～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-讯"},{"id":"glyph-seal-8bb0","script":"seal","character":"记","reading":"jì","description":"记载,记录\n记,书也。\n⒈思念，把所见、所闻等事物保持在脑子里，跟\"忘\"相对惦～。牢～。～性强。～得住。\n⒋印章图～。戳～。\n⒌标志～号。暗～。\n⒍量词他挨了两～耳光。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-记"},{"id":"glyph-seal-8bb2","script":"seal","character":"讲","reading":"jiǎng","description":"⒈谈，说～普通话。～故事。\n⒉解释，说明～解。～课。\n⒊注重，顾到，谋求～清洁。～政策。～团结。\n⒋商讨，商议～价。～条件。\n①注重，探求～究整洁。～究效益。\n②精致，美观这个实验室相当～究。\n③一定的方法、道理或值得注意的翻译外国文学，在技巧上是大有～究的。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-讲"},{"id":"glyph-seal-8bb3","script":"seal","character":"讳","reading":"huì","description":"隐;隐蔽\n⒈隐瞒，避忌，有顾忌不敢说或不愿说～莫如深。～疾忌医。无庸～言。不必忌～。\n⒉封建时代称死去了的皇帝或长者的名姓刘～邦。姓曹～操。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-讳"},{"id":"glyph-seal-8bb4","script":"seal","character":"讴","reading":"ōu","description":"歌颂;赞颂\n歌曲\n京洛出名讴\n⒈唱歌歌～。\n⒉歌曲名～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-讴"},{"id":"glyph-seal-8bb5","script":"seal","character":"讵","reading":"jù；jv","description":"岂,难道\n无;非;不\n不料,哪知\n如果\n讵jù岂，难道，哪里～料。～知。～可闻？","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-讵"},{"id":"glyph-seal-8bb6","script":"seal","character":"讶","reading":"yà","description":"诧异,感到意外\n责怪\n讶yà惊奇，诧异惊～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-讶"},{"id":"glyph-seal-8bb7","script":"seal","character":"讷","reading":"nè；nei","description":"结结巴巴地说\n忍而少言\n讷nè语言迟钝，不善于讲话口～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-讷"},{"id":"glyph-seal-8bb8","script":"seal","character":"许","reading":"xǔ","description":"⒈应允，认可～可。允～。准～。\n⒉称赞赞～。推～。\n⒊预先答应给予～诺。以身～国。\n⒋可能，或者也～。或～。\n⒌处所，地方先生不知何～人也。\n⒍〈表〉约略估计的几～。只有少～。年七十～。\n⒎句末语气词。这样如～。一生长恨奈何～。\n⒏周代诸侯国名，在今河南省许昌一带。\n许hǔ 1.见\"许许\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-许"},{"id":"glyph-seal-8bba","script":"seal","character":"论","reading":"lùn","description":"论语\n议论, 分析和说明事理\n坐而论道。\n⒈商讨，判断，研究讨～。议～。评～。争～。就事～事。\n⒉主张，学说进化～。唯物～。\n⒊文体名。论述事物的内容、意义，阐明道理～文。社～。实践～。\n⒋衡量，评定～罪。\n⒌按照～件计酬。～质核价。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-论"},{"id":"glyph-seal-8bbc","script":"seal","character":"讼","reading":"sòng","description":"打官司\n⒈争论，争辩辩～。聚～纷纭。\n⒉在法庭上争辩，打官司～事。诉～。\n⒊公开未敢～言。\n⒋〈古〉通\"颂\"。赞美，颂扬。\n讼róng 1.容纳。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-讼"},{"id":"glyph-seal-8bbd","script":"seal","character":"讽","reading":"fěng","description":"婉言微辞或指责\n⒈用含蓄的话词劝告或讥刺谈笑～谏。～刺小品。挖苦讥～。\n⒉背书，不看着书本子念读～诵。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-讽"},{"id":"glyph-seal-8bbe","script":"seal","character":"设","reading":"shè","description":"⒈布置，装置，安排～置。～立。～防。\n⒉筹划，规划，制定方案、图样等～法。～想。～计。\n⒊假使，如果，若是，假想～若。～如。～或。假～。\n①工作上、生产上、生活上等所需要的各种设施和器械用品。\n②设置以备施用。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-设"},{"id":"glyph-seal-8bbf","script":"seal","character":"访","reading":"fǎng","description":"⒈询问，调查～贫济困。查～。采～。\n⒉探望～亲会友。相～。探～。拜～。〈引〉寻求～求。\n⒊查，侦察明察暗～。\n【访问】有目的地探望～问水稻专家。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-访"},{"id":"glyph-seal-8bc0","script":"seal","character":"诀","reading":"jué","description":"早知诀汝。\n通决”。自杀\n⒈辞别，多指长别，永别与母～。～别。永～。\n⒉窍门，高明的办法～窍。这是秘～。她有妙～。\n⒊使用事物的主要内容编成顺口的便于记忆的词句编口～。写歌～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-诀"},{"id":"glyph-seal-8bc1","script":"seal","character":"证","reading":"zhèng","description":"谏正\n通症”。病症\n假借为徵”。今亦用为譪验字。证据\n⒈以人物、事实来表明或断定～人。～物。～明。～实。～几何题。\n⒉凭据，帮助断定的东西～据。物～。居民身份～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-证"},{"id":"glyph-seal-8bc2","script":"seal","character":"诂","reading":"gǔ","description":"后汉桓谭传郑兴传注皆引说文、训古言也\n古言古义;词语的意义\n诂gǔ对古代语言文字或方言字义的解释释～。训～。字～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-诂"},{"id":"glyph-seal-8bc3","script":"seal","character":"诃","reading":"hē","description":"〔～子〕常绿乔木，果实像橄榄，可入药。亦称藏青果”。\n⒈同\"呵","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-诃"},{"id":"glyph-seal-8bc5","script":"seal","character":"诅","reading":"zǔ","description":"盟誓,特指就小事或往事起誓\n⒈迷信者所谓\"祈求神灵加祸于所憎恨的人\"～人伤自身。\n⒉盟誓～约。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-诅"},{"id":"glyph-seal-8bc6","script":"seal","character":"识","reading":"shí","description":"⒈知道，认得，能辨别～字。认～。～别。～途老马。\n⒉学问，应知的，所知道的学～。知～。常～。有～之士。\n⒊见解，辨别是非的能力见～。远见卓～。\n⒈记住，做记号，也指记号、标志博闻强～。表～。款～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-识"},{"id":"glyph-seal-8bc8","script":"seal","character":"诈","reading":"zhà","description":"假装;冒充\n⒉假装～败。～病。～降。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-诈"},{"id":"glyph-seal-8bc9","script":"seal","character":"诉","reading":"sù","description":"告诉,说给人听\n吾与并\n⒈叙说叙～。～苦。详细～说。\n⒉控告～讼。上～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-诉"},{"id":"glyph-seal-8bca","script":"seal","character":"诊","reading":"zhěn","description":"医生为断定疾症而察看病人身体内部、外部的情况门～。～断。～室。～脉。\n察看，验证匠石觉而～其梦”。\n诊zhěn看病，检查病人就～。～病。～断。随到随～。巡廻～治。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-诊"},{"id":"glyph-seal-8bcb","script":"seal","character":"诋","reading":"dǐ","description":"谴责\n诋 dǐ毁谤；说坏话～毁。\n【诋毁】毁谤；诬蔑。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-诋"},{"id":"glyph-seal-8bcd","script":"seal","character":"词","reading":"cí","description":"诗文中的词语\n①言词；词句歌～、～不达意。\n②一种韵文形式，由五言诗、七言诗和民歌发展而来，形成于唐代，盛行于宋代。有小令和慢词两种，一般分上下两阕。\n③语言中最小的有意义的可以自由运用的单位。\n【词不达意】所用词语不能清楚地表达意思。\n【词典】汇集语言里的词语，按某种次序排列，并一一加以解释的一种工具书。\n【词法】语言学上的形态学。内容包括词的构造、词的变化、词的分类等。\n【词根】体现基本意义的语素。如'师''杯'分别为、'老师'、'杯子'两词的词根。\n【词汇】\n①一种语言里所使用的词的总汇。\n②一部作品或一个人所用的词的总汇。\n【词类】词在语法上按照不同语法功能的分类。如名词、动词、形容词、副词等。\n【词类活用】甲类词在特定的条件下，为了表达上的需要，偶尔用作乙类。如'夏雨雨人'，第二个'雨'字活用为动词，念去声，'雨打'之意。\n【词类转化】指由一个词类转化为另一个词类。如英语的water，本为名词'水'，可以转化为动词'浇水'。\n【词令】见【辞令】。\n【词牌】填词用的曲调名。最初的词，为了配合音乐来歌唱，要按词制调或依调填词，曲调的名称要根据词的内容而定◇来多数词已不再配乐歌唱，词牌已变为填词时文字、\n音韵的结构定式。\n【词性】","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-词"},{"id":"glyph-seal-8bcf","script":"seal","character":"诏","reading":"zhào","description":"教导;告诫\n夫为人父者,必\n⒈告戒，教诲～告。～教。\n⒉皇帝的命令或文告～令。～书。\n诏shào 1.承继。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-诏"},{"id":"glyph-seal-8bd1","script":"seal","character":"译","reading":"yì","description":"解释;阐述\n通择”。选择\n周道衰微,失爵亡邦,后嗣乖散,各\n①翻译。把一种语言文字转换成另一种语言文字。\n②指翻译人员。\n③指语言不通的异域。\n④阐述;诠释。\n⑤变易，改变。如\"译形借声\"。\n⑥通\"绎\"。寻绎。\n⑦通\"擇\"。选择。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-译"},{"id":"glyph-seal-8bd2","script":"seal","character":"诒","reading":"yí","description":"遗留\n给予;赠送\n⒈遗留～训。\n⒉赠给，送给～书。\n⒊欺骗骨肉相～，朋友相诈。\n诒dài 1.欺骗。\n诒tái 1.懈倦貌。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-诒"},{"id":"glyph-seal-8bd4","script":"seal","character":"诔","reading":"lěi","description":"哀悼死者的文章\n诔lěi〈古〉叙述死者生平并表达哀悼的文章◇成为一种哀祭文体。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-诔"},{"id":"glyph-seal-8bd5","script":"seal","character":"试","reading":"shì","description":"尝试\n⒈按预定想法非正式的做～做。～车。～ ～看。\n⒉检验，品尝～验。尝～。\n⒊考，测验考～。口～。笔～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-试"},{"id":"glyph-seal-8bd6","script":"seal","character":"诖","reading":"guà","description":"欺骗\n⒈牵累，连累。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-诖"},{"id":"glyph-seal-8bd7","script":"seal","character":"诗","reading":"shī","description":"⒈文体名。形式很多，它是可以歌咏或朗诵的韵文。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-诗"},{"id":"glyph-seal-8bd8","script":"seal","character":"诘","reading":"jié","description":"责备;质问\n仲冬之月…农有不收藏积聚者,马牛畜兽有\n⒉见jí。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-诘"},{"id":"glyph-seal-8bda","script":"seal","character":"诚","reading":"chéng","description":"真实\n②实在；的确；～然。\n【诚笃】诚实真挚。\n【诚惶诚恐】原为封建时代臣下给皇帝奏章中的套语，表示敬畏之意。形容十分谨慎恐慌不安的样子。有时含讽刺意味。\n【诚然】\n①实在；的确这本书～可以一读。\n【诚心诚意】实心实意。形容十分诚挚。\n【诚挚】诚恳真挚。\n⒈真心，不虚伪～实。～挚。～信。真～。～心～意。\n⒉确实，的确～然。～说此言。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-诚"},{"id":"glyph-seal-8bdb","script":"seal","character":"诛","reading":"zhū","description":"杀戮。夺去生命\n立诛杀曹无伤\n⒈杀死，铲除～戮ˇ民者～。～锄杂草。\n⒉谴责，责罚，讨伐口～笔伐。兴兵～之。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-诛"},{"id":"glyph-seal-8bdc","script":"seal","character":"诜","reading":"shēn","description":"众多的样子\n①先致其言，纷纷传言。\n②问。\n③众多貌。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-诜"},{"id":"glyph-seal-8bdd","script":"seal","character":"话","reading":"huà","description":"话题\n话本;故事\n授意表达的言词\n⒈语言讲～。普通～。\n⒉说，谈～别离。茶～会。～不投机。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-话"},{"id":"glyph-seal-8bde","script":"seal","character":"诞","reading":"dàn","description":"虚妄;荒唐\n①出生～生。\n②生日～辰、华～。\n③荒唐的；不合情理的荒～、怪～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-诞"},{"id":"glyph-seal-8bdf","script":"seal","character":"诟","reading":"gòu","description":"⒈耻辱～莫大于宫刑。\n⒉辱骂当众～骂。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-诟"},{"id":"glyph-seal-8be0","script":"seal","character":"诠","reading":"quán","description":"通铨”。权衡;考虑;比较\n通铨”。选择\n⒈解释，阐明事理～释。～论。\n①阐述真理的语句。\n②真理衣褐向真～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-诠"},{"id":"glyph-seal-8be1","script":"seal","character":"诡","reading":"guǐ","description":"违反,自相矛盾\n⒈欺诈，奸滑～计。～辩。\n⒉奇异，怪异，出乎平常～谲。～殊。～秘。～异。\n⒊违反，违背～于常理。言行相～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-诡"},{"id":"glyph-seal-8be2","script":"seal","character":"询","reading":"xún","description":"询xún问，请教，征求意见～问。探～。查～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-询"},{"id":"glyph-seal-8be3","script":"seal","character":"诣","reading":"yì","description":"晋谒;造访。古代到朝廷或上级、尊长处去之称\n⒈往，到～京。特指到尊长处专～请教。\n⒉［造诣］学问、技术等所达到的境地她对生物学造～很深。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-诣"},{"id":"glyph-seal-8be4","script":"seal","character":"诤","reading":"zhèng","description":"假借为争”。争论;争讼\n争奇;竞争\n通争”。争夺\n有两虎诤人而\n诤zhèng谏，直言劝告～言。～友。谏～。\n诤zhēng 1.通\"争\"。争讼﹔争论。 2.通\"争\"。争夺﹔争竞。 3.用同\"睁\"。瞪大着眼睛。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-诤"},{"id":"glyph-seal-8be5","script":"seal","character":"该","reading":"gāi","description":"同引申义\n广博\n包容;包括\n⒈应当应～。自己～做的事，一定要抓紧做好。\n⒉〈表〉从推测到必然的或可能的结果她～到家了。\n⒊欠～她的钱。\n⒋那，那个，特指前面说过的人或事物～人。～处。～事。\n⒌〈古〉同\"赅\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-该"},{"id":"glyph-seal-8be6","script":"seal","character":"详","reading":"xiáng","description":"详细说明\n清楚地知道\n⒈细密，完备～细。～尽。～情。～实。～议法令。\n⒉清楚，知道内容～知。\n⒊说明，细说～谈。内～。～告之。\n⒋广泛，周遍～找。\n⒍〈古〉通\"佯\"。假装。\n详yáng 1.诈，假装。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-详"},{"id":"glyph-seal-8be9","script":"seal","character":"诩","reading":"xǔ","description":"普及\n假借为妩”。妩媚\n诩xǔ夸耀，说大话。夸～。自～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-诩"},{"id":"glyph-seal-8beb","script":"seal","character":"诫","reading":"jiè","description":"规劝\n警诫\n规劝告诫之文\n⒈警告，劝告告～。劝～。～勉。\n⒉警戒，戒备前车覆，后车～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-诫"},{"id":"glyph-seal-8bec","script":"seal","character":"诬","reading":"wū","description":"欺骗\n无中生有,捏造事实害人\n诬去贤使君。\n诬太守者。\n抹杀","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-诬"},{"id":"glyph-seal-8bed","script":"seal","character":"语","reading":"yǔ","description":"交谈,说话\n既歌而语。\n⒈说，谈寡言少～。自言自～。\n⒉话，言论～言『～。外～。成～。\n⒊代替说话的动作手～。旗～。\n⒋简单的俗话或古句谚～。古～。～曰。\n⒌虫、鸟的鸣声蝉～。鸟～。\n语ｙù告诉莫～人。\n语yù 1.告诉。 2.通\"悟\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-语"},{"id":"glyph-seal-8bee","script":"seal","character":"诮","reading":"qiào","description":"嘲讽\n简直,完全\n⒈讥讽讥～。\n⒉责备，谴责～他几句。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-诮"},{"id":"glyph-seal-8bef","script":"seal","character":"误","reading":"wù","description":"谬误;错误\n耽误\n妨害\n⒈错，荒谬～差。～会。错～。谬～。\n⒉耽搁～事。～点。耽～。\n⒊使受害～人子弟。～国～民。\n⒋不是故意的但有害于人～伤。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-误"},{"id":"glyph-seal-8bf0","script":"seal","character":"诰","reading":"gào","description":"⒈〈古〉帝王给臣子的命令诏～。制～。封～。\n⒉文体的一种，用于告戒或劝勉。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-诰"},{"id":"glyph-seal-8bf1","script":"seal","character":"诱","reading":"yòu","description":"引诱\n向导,引\n⒈引导，教导，劝导～导。循循善～。\n⒉使用计策或手段迷惑、招引别人引～。利～。～骗。～惑。～敌深入。\n⒊吸引景色～人。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-诱"},{"id":"glyph-seal-8bf2","script":"seal","character":"诲","reading":"huì","description":"明示,诱使\n教导的话\n诲huì教导，指教教～。学而不厌，～人不倦。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-诲"},{"id":"glyph-seal-8bf3","script":"seal","character":"诳","reading":"kuáng","description":"诳kuáng欺骗，迷惑～语。～言。他在～人。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-诳"},{"id":"glyph-seal-8bf4","script":"seal","character":"说","reading":"shuō；shui","description":"说服;劝说\n休憩;止息。通税”\n⒈〈古〉同\"悦\"。\n⒈说动别人，使他听从自己的意见～客。游～。\n⒈讲话，用话表达意思你～。～到做到。\n⒉言论，主张学～。著书立～。\n⒊批评，指责～了他几句。\n⒋解释解～。一～就懂。\n说tuō 1.简易。参见\"说唃\"。 2.通\"脱\"。解脱;免除。 3.通\"脱\"。急骤。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-说"},{"id":"glyph-seal-8bf5","script":"seal","character":"诵","reading":"sòng","description":"⒈背读，用抑扬高低的腔调念背～。朗～。\n⒉述说，陈述～功。\n⒊诗篇作～。\n⒋〈古〉通\"讼\"。公开。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-诵"},{"id":"glyph-seal-8bf7","script":"seal","character":"请","reading":"qǐng","description":"通情”。情况,实情\n请求;要求\n⒈求，请求～示。～假。～命。～战。\n⒉敬词。用于动词前～进。～坐。～喝茶。\n⒊邀请，邀约，延聘～客。～医师。～专家指导。聘～教师。\n请qìng 1.朝会名。\n请qíng 1.后又作\"?\"。认领;接受。 2.通\"情\"。实情;情况。 3.通\"情\"。实在;的确。 4.通\"情\"。情感。\n请qīng 1.参见\"请靓\"﹑\"请室\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-请"},{"id":"glyph-seal-8bf8","script":"seal","character":"诸","reading":"zhū","description":"众;各\n诸将皆失色。\n仆必能从\n⒈各，众，许多～军。～位。～君。～子百家。\n诸chú 1.蟾蜍。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-诸"},{"id":"glyph-seal-8bf9","script":"seal","character":"诹","reading":"zōu","description":"挑选\n商议","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-诹"},{"id":"glyph-seal-8bfa","script":"seal","character":"诺","reading":"nuò","description":"古时批字于公文之尾,表示许可叫诺”,犹今签字\n诺贝尔\n⒈答应，应允～言。\n⒉答应声，〈表〉同意～～连声。唯唯～～","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-诺"},{"id":"glyph-seal-8bfb","script":"seal","character":"读","reading":"dú","description":"籀书,抽释理解书的意义\n阅读\n读 dòu语句中的停顿。古代诵读文章时，完整的长句或小段的停顿称为'句'，'句'中的小停顿称为'读'。又见dú。\n①照着文字念。\n②阅读；看书或文章。\n②上学～大学。又见dòu。\n【读后感】一种文体。读书看报之后，把心得、感受、看法等写成文章或笔记。\n【读卖新闻】日本最有影响的报纸之一。1874年创刊。面向大众，注重社会新闻和体育新闻。每天早刊24版，晚刊12版。\n【读秒】\n①围棋、象棋等体育比赛规则。对局者自由支配时间已用到事先规定的保留时限后始由裁判员报时。\n②比喻非常紧张繁忙的状态或阶段亚运工程已进入～阶段。\n【读数据语句】〈计〉basic语言语句之一。它向运行中的程序的某些变量提供数据。date语句设置数据表，由read语句提取数据，每提取一个数据时，指向下一个将要提取的\n数据位置。\n【读友】〈港台〉读者。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-读"},{"id":"glyph-seal-8bfd","script":"seal","character":"诽","reading":"fěi","description":"毁谤","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-诽"},{"id":"glyph-seal-8bfe","script":"seal","character":"课","reading":"kè","description":"督促完成指定的工作\n按规定的内容和分量讲授或学习\n⒈学校里教学的科目、进程政治～。数学～。～程表。上～了。\n⒉督促完成工作任务宜严～农桑。〈引〉教授或学习～徒。～读。昼～赋，夜～书，间又～诗。\n⒊旧指规定的赋税，也指征收赋税国～。～以重税。\n⒋机关、学校等单位分设的办事部门出纳～。教务～。\n⒌试验，考核不～不用。\n⒍迷信者的骗术活动，占卜的一种起～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-课"},{"id":"glyph-seal-8bff","script":"seal","character":"诿","reading":"wěi","description":"推托;推委\n委托;连累\n诿过\n出了问题不诿过\n诿过于人\n诿卸\n诿wěi通\"委\"。推卸不要推～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-诿"},{"id":"glyph-seal-8c00","script":"seal","character":"谀","reading":"yú","description":"谄媚的话\n唯囿是恢,唯谀是信。╠\n谀yú奉承，谄媚～辞。阿～。谄～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谀"},{"id":"glyph-seal-8c01","script":"seal","character":"谁","reading":"shuí","description":"哪个人或哪些人\n某人\n每个人\n表示疑问。指事物,相当于什么”\n⒈疑问代词。什么人～在说话？\n⒉任何人这件事～都能做。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谁"},{"id":"glyph-seal-8c02","script":"seal","character":"谂","reading":"shěn","description":"告诉\n通念”。思念\n知悉\n通渧”。躲闪,鱼惊走\n故龙以为畜而鱼\n⒈通\"审\"知道～知。～悉。\n⒉劝谏。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谂"},{"id":"glyph-seal-8c03","script":"seal","character":"调","reading":"diào","description":"盐或提拔官吏\n征用,提取,征发\n调动\n我是个调虎离山\n①调动；分派～离、～兵谴将。\n②曲调音乐上高低长短配合而成的一组音二黄～、咏叹～。\n③调式；决定整首乐曲取音高低的类别f大～。\n④声调。也指说话、读书、朗诵的腔调。又见tiáo。\n【调号】〈音〉音乐符号。指定乐曲主音高度的符号。五线谱中在g谱号、f谱号或c谱号上加升记号或降记号来标明，标记在各行谱表的最左方。简谱中用1=c或1=g等符号，标\n记在乐曲的左上方。\n【调虎离山】比喻用计谋调动对方离开原来的有利地位，乘机达到自己的目的。\n【调遣】调派；分派。\n【调性】〈音〉调式类别与主音高度本身所具有的特质。如以c音为主音的大调式称c大调；以a音为主音的小调式称a小调。\n⒈配合均匀适当～色。～味。风～雨顺。\n⒊戏弄，挑逗～戏。～唆。～拨。～情。\n⒋顽皮，爱开玩笑～皮。\n①配药。\n②调配，调整，使均匀适当～剂。～剂原料。\n调zhōu 1.朝，早晨。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-调"},{"id":"glyph-seal-8c04","script":"seal","character":"谄","reading":"chǎn","description":"谄 chǎn奉承；巴结～谀。\n【谄媚】用卑贱的态度巴结人。\n【谄上欺下】对上讨好巴结，对下欺侮压制。\n【谄谀】谄媚阿谀。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谄"},{"id":"glyph-seal-8c05","script":"seal","character":"谅","reading":"liàng","description":"固执,坚持己见\n谅解\n⒈原谅，体谅见～。～我此心。\n⒉料想～必。～他不敢。\n⒊诚信～哉斯言。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谅"},{"id":"glyph-seal-8c06","script":"seal","character":"谆","reading":"zhūn","description":"诚恳;忠诚\n谆zhūn恳切。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谆"},{"id":"glyph-seal-8c07","script":"seal","character":"谇","reading":"suì","description":"劝告;谏诤\n责问;用责备的口气问\n古乐章的尾声。相当于乱”\n⒈骂，责怪。\n⒉直言规劝。\n⒊问。\n⒋告知。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谇"},{"id":"glyph-seal-8c08","script":"seal","character":"谈","reading":"tán","description":"相处融洽\n⒉言论奇～怪论。高～阔论。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谈"},{"id":"glyph-seal-8c0a","script":"seal","character":"谊","reading":"yì","description":"意义,意思\n友情,友好关系\n谊yì交情，情意友～。深情厚～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谊"},{"id":"glyph-seal-8c0b","script":"seal","character":"谋","reading":"móu","description":"肉食者谋之。\n⒈计划，计策，主意～划。～略。计～。足智多～。\n⒉商议，商量不～而合。\n⒊设法寻求为人民～幸福。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谋"},{"id":"glyph-seal-8c0c","script":"seal","character":"谌","reading":"chén","description":"相信\n真诚,忠诚\n①相信。\n②确实如此；诚然。\n③姓。\n⒈诚然，的确～称一绝。\n⒉信，相信。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谌"},{"id":"glyph-seal-8c0d","script":"seal","character":"谍","reading":"dié","description":"间谍\n传递的情报\n通牒”。书札\n①秘密刺探军事、政治及经济方面的情报～报。\n②进行谍报活动的人间～。\n【谍报】\n①刺探到的情报。\n②将刺探到的情报交给上级或有关方面。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谍"},{"id":"glyph-seal-8c0e","script":"seal","character":"谎","reading":"huǎng","description":"梦中讲的话\n不公平或欺骗的价格\n哄骗,用假话或手段骗人\n虚假\n⒈骗人，假话～骗。～话。～报。莫撒～。〈引〉商贩要的虚价要～。\n⒉说谎话～称。～说。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谎"},{"id":"glyph-seal-8c0f","script":"seal","character":"谏","reading":"jiàn","description":"谏jiàn〈古〉规劝君主、尊长或朋友，使其改正错误或过失进～。力～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谏"},{"id":"glyph-seal-8c10","script":"seal","character":"谐","reading":"xié","description":"言语或行为有趣而引人发笑\n心亲不复异新旧,使脱\n⒈融洽，配合适当～作⊥～。\n⒉滑稽，谈笑随便诙～。～谈。亦庄亦～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谐"},{"id":"glyph-seal-8c11","script":"seal","character":"谑","reading":"xuè；nue","description":"取笑作乐\n谑xuè开玩笑戏～。调笑来相～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谑"},{"id":"glyph-seal-8c12","script":"seal","character":"谒","reading":"yè","description":"告发;检举\n请;请求\n谒yè请见，拜见～见。拜～。～烈士墓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谒"},{"id":"glyph-seal-8c13","script":"seal","character":"谓","reading":"wèi","description":"谓唐雎曰。\n不可谓仁。\n不可谓忠。\n不可谓知类。\n评论\n⒈说，告诉可～。愚公～智叟曰。\n⒉叫做，称为，因为～之。称～∥～？\n⒋意义无～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谓"},{"id":"glyph-seal-8c15","script":"seal","character":"谕","reading":"yù","description":"明白、懂得\n旧时用指上对下的文告、指示\n⒉〈古〉同\"喻\"。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谕"},{"id":"glyph-seal-8c16","script":"seal","character":"谖","reading":"xuān","description":"忘记,忘却,遗忘\n①欺诈。\n②通\"萱\"。忘记。\n③引申为停止。\n④通\"諠\"。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谖"},{"id":"glyph-seal-8c17","script":"seal","character":"谗","reading":"chán","description":"说别人坏话的人\n谗 chán说别人的坏话进～言。\n【谗害】通过说坏话陷害人。\n【谗言】陷害别人的坏话。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谗"},{"id":"glyph-seal-8c19","script":"seal","character":"谙","reading":"ān","description":"熟记\n⒈熟悉～练。\n⒉知道，精通深～医术。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谙"},{"id":"glyph-seal-8c1a","script":"seal","character":"谚","reading":"yàn","description":"通唁”。慰问死者家属\n粗野不恭\n乃逸乃谚,既\n谚yàn谚语，社会上流传的简练、通俗、具有固定性的语言民～。古～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谚"},{"id":"glyph-seal-8c1b","script":"seal","character":"谛","reading":"dì","description":"明白;了解\n详细,仔细\n佛教名词。谓真实无谬的道理\n事物的\n②道理；真理真～。\n谛tí 1.号哭。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谛"},{"id":"glyph-seal-8c1c","script":"seal","character":"谜","reading":"mí","description":"猜谜儿\n謎谜  mi\n而君子嘲隐,化为谜语。\n没有弄清楚的事物\n谜底\n谜语的答案\n谜团\n谜团\n难解的谜团\n谜语","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谜"},{"id":"glyph-seal-8c1d","script":"seal","character":"谝","reading":"piǎn","description":"花言巧语\n欺骗;诈骗\n谝pián 1.巧言。 2.欺骗;诈骗。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谝"},{"id":"glyph-seal-8c1f","script":"seal","character":"谟","reading":"mó","description":"通无”。没有\n谟mó计划，谋略宏～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谟"},{"id":"glyph-seal-8c20","script":"seal","character":"谠","reading":"dǎng","description":"正直，言论公正，如谠言、谠论。","enabled":true,"collection":"篆字扩展","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-8c22","script":"seal","character":"谢","reading":"xiè","description":"用言辞委婉地推辞拒绝\n⒈感激～ ～你。感～。\n⒉道歉，认错～过。～罪。\n⒊〈古〉告诉多～后世人。\n⒋推辞，辞别～绝。～客。\n⒌衰亡，凋落新陈代～。花～花落。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谢"},{"id":"glyph-seal-8c24","script":"seal","character":"谤","reading":"bàng","description":"诽谤","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谤"},{"id":"glyph-seal-8c25","script":"seal","character":"谥","reading":"shì","description":"弟子加谥号的称\"私谥\"，如陶渊明私谥\"靖节\"。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谥"},{"id":"glyph-seal-8c26","script":"seal","character":"谦","reading":"qiān","description":"通\"嫌\"。嫌疑\n贵而不为\n谦qiān虚心，不自满～虚。～逊。～让。～恭。～受益。\n谦qiè 1.满足;快意。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谦"},{"id":"glyph-seal-8c27","script":"seal","character":"谧","reading":"mì","description":"谧mì安宁，平静～静。安～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谧"},{"id":"glyph-seal-8c28","script":"seal","character":"谨","reading":"jǐn","description":"以谨罔极。\n恭敬\n⒈慎重，小心～慎。～防。～遵法令。\n⒉敬词。〈表〉郑重，恭敬～启。～呈。～具此证。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谨"},{"id":"glyph-seal-8c29","script":"seal","character":"谩","reading":"màn","description":"抵赖\n毁谤;谩骂\n乡则不若,偝则谩之,是人\n⒈欺骗欺～。\n⒉诋毁背则～之。\n谩màn通\"慢\"。\n⒈傲慢，没有礼貌～骂。轻～。\n⒉怠慢～怠。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谩"},{"id":"glyph-seal-8c2a","script":"seal","character":"谪","reading":"zhé","description":"降职并外放\n⒈谴责，责罚众口交～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谪"},{"id":"glyph-seal-8c2c","script":"seal","character":"谬","reading":"miù","description":"⒈错误，与客观事实不符～论。～误。荒～。大～。\n⒉差误差以毫厘，～以千里。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谬"},{"id":"glyph-seal-8c2e","script":"seal","character":"谮","reading":"zèn","description":"谮zèn说坏话诬陷别人～言。\n谮jiàn 1.不信。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谮"},{"id":"glyph-seal-8c2f","script":"seal","character":"谯","reading":"qiáo","description":"城门上的望楼\n古县名\n通瞧”。瞭望\n通诮”。责备\n谯楼\n谯qiào 1.责备;谴责。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谯"},{"id":"glyph-seal-8c30","script":"seal","character":"谰","reading":"lán","description":"诬赖,诬陷\n欺骗\n谰调\n谰言\n谰lán抵赖，欺骗，诬陷抵～。谩～。无耻～言。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谰"},{"id":"glyph-seal-8c31","script":"seal","character":"谱","reading":"pǔ","description":"符号或文字列记乐歌的音节、声调,以便奏唱的籍录\n⒈记载事物类别、系统等的表册或书籍菜～。年～。家～。\n⒉记录音乐、棋局等符号、图形的样本或书册曲～。乐～。五线～。棋～。画～。\n⒊按歌词作曲～曲。\n⒋大致的准则，把握心中有～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谱"},{"id":"glyph-seal-8c32","script":"seal","character":"谲","reading":"jué","description":"欺骗;诈骗\n通决”。判断,判别\n诡诈\n怪异\n谲jué欺诈，玩弄手段～妄。诡～狡诈。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谲"},{"id":"glyph-seal-8c34","script":"seal","character":"谴","reading":"qiǎn","description":"旧时官吏被贬或谪戍\n⒈责备～责。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谴"},{"id":"glyph-seal-8c36","script":"seal","character":"谶","reading":"chèn","description":"谶纬\n谶纬之学\n谶语\n当时无意中说出,不意日后竟成谶语\n谶 chèn迷信的人所称将来能应验的预言、预兆。\n【谶纬】流行于汉代的一种迷信。主要以古代河图、洛书的神话及西汉董仲舒的天人感应说为理论依据，将自然界的偶然现象神秘化，并视为社会安定的决定因素。盛行于西汉\n后期，东汉末期渐衰。\n【谶语】迷信的人指事前预言、事后应验的话。\n谶chèn迷信者宣扬的所谓\"日后会应验的预言、预兆\"莫信～语。\n谶chàn 1.忏悔。参见\"谶悔\"。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谶"},{"id":"glyph-seal-8c37","script":"seal","character":"谷","reading":"gǔ","description":"两山之间的水流\n泉出通川为谷\n⒈庄稼和粮食的总称种～。～物。～贵饿农。～贱伤农。\n⒌见yù、lù。榖gǔ榖树，也叫\"构\"或\"楮\"。落叶乔木，花淡绿色，果实红色。树皮纤维可以造纸。\n谷gòu 1.小孩。 2.古代楚语谓乳。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-谷"},{"id":"glyph-seal-8c41","script":"seal","character":"豁","reading":"huō","description":"huō：(1)残缺，裂开～口。～子（残缺的口子）。\n(2)舍弃～出性命。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-豁"},{"id":"glyph-seal-8c46","script":"seal","character":"豆","reading":"dòu","description":"dòu：(1)双子叶植物的一科，木本、草本植物都有，如紫檀”、槐树”、黄豆”、绿豆”、红豆”、豌豆”、落花生”等，日常统称豆类植物，亦指这些植物的种子～科。～子。～荚（豆角儿）。～浆。～绿。煮～燃萁。目光如～。\n(2)形状像豆粒的东西土～儿。\n(3)古代盛肉或其他食品的器皿，形状像高脚盘俎～。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-豆"},{"id":"glyph-seal-8c49","script":"seal","character":"豉","reading":"chǐ","description":"chǐ：〔豆～〕一种用熟的黄豆或黑豆经发酵后制成的食品。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-豉"},{"id":"glyph-seal-8c55","script":"seal","character":"豕","reading":"shǐ","description":"豕shǐ猪～突（突冲撞）狼奔（〈喻〉坏人到处乱闯，任意破坏）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-豕"},{"id":"glyph-seal-8c5a","script":"seal","character":"豚","reading":"tún","description":"tún：小猪，亦泛指猪～肩。～蹄。～儿（谦称自己的儿子）。\n〔～鼠〕哺乳动物，亦称荷兰猪”、天竺鼠”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-豚"},{"id":"glyph-seal-8c61","script":"seal","character":"象","reading":"xiàng","description":"xiàng：(1)哺乳动物，是地球上最大的动物，多产在印度、非洲等热带地区，门牙极长，可用于雕刻成器皿或艺术品～牙。～牙宝塔（喻脱离群众和生活的文学家、艺术家的小天地）。\n(2)形状，样子形～。景～。气～。现～。想～。～征。万～更新。～声。～形。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-象"},{"id":"glyph-seal-8c62","script":"seal","character":"豢","reading":"huàn","description":"huàn：喂养，特指喂养牲畜～养。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-豢"},{"id":"glyph-seal-8c68","script":"seal","character":"豨","reading":"xī","description":"⒈〈古〉指猪。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-豨"},{"id":"glyph-seal-8c6a","script":"seal","character":"豪","reading":"háo","description":"háo：(1)具有杰出才能的人～杰。英～。文～。自～。\n(2)气魄大，直爽痛快，没有拘束的～放。～爽。～迈。～气。～情。～兴（xìng）。～举。～语。～华。\n(3)强横的，有特殊势力的～强。～门。～族。～绅。巧取～夺。\n(4)古同毫”，极小。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-豪"},{"id":"glyph-seal-8c6b","script":"seal","character":"豫","reading":"yù","description":"yù：(1)欢喜，快乐～附。～游（逸乐嬉游）。不～之色。\n(2)同预”。\n(3)安闲，舒适逸～。\n(4)古同与”，参与。\n(5)中国河南省的别称～剧（亦称河南梆子”）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-豫"},{"id":"glyph-seal-8c73","script":"seal","character":"豳","reading":"bīn","description":"bīn：古地名，在今中国陕西省旬邑县西南。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-豳"},{"id":"glyph-seal-8c78","script":"seal","character":"豸","reading":"zhì","description":"zhì：(1)古书上说的没有脚的虫虫～（虫子的通称）。\n(2)解决。\n〔獬～〕见獬”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-豸"},{"id":"glyph-seal-8c79","script":"seal","character":"豹","reading":"bào","description":"bào：(1)哺乳动物，能上树，常捕食鹿、羊、猿猴等，毛皮可制衣、褥～头环眼（形容人面目威严凶狠）。未窥全～。\n(2)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-豹"},{"id":"glyph-seal-8c7a","script":"seal","character":"豺","reading":"chái","description":"chái：哺乳动物，贪食，残暴，常成群侵袭家畜。分布于中国及俄罗斯西伯利亚、印度尼西亚等地（亦称豺狗”）～狼。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-豺"},{"id":"glyph-seal-8c82","script":"seal","character":"貂","reading":"diāo","description":"diāo：哺乳动物的一属。种类很多，毛皮黄黑色或带紫色，是很珍贵的衣料，我国东北特产之一。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-貂"},{"id":"glyph-seal-8c89","script":"seal","character":"貉","reading":"mò；hé；háo","description":"hé：哺乳动物，外形像狐，穴居河谷、山边和田野间；杂食鱼、鼠、蛙、虾、蟹和野果、杂草等，皮很珍贵一丘之～。\nháo：义同（一），用于貉子”、貉绒”。\nmò：古同貊”①。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-貉"},{"id":"glyph-seal-8c8c","script":"seal","character":"貌","reading":"mào","description":"mào：(1)面容面～。容～。～相。以～取人。\n(2)外表的样子礼～。～合神离。道～岸然。\n(3)外观全～。\n(4)古书注解里表示状态、样子，如飞貌”指飞的样子。\n(5)描绘，画像命工～妃于别殿”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-貌"},{"id":"glyph-seal-8c94","script":"seal","character":"貔","reading":"pí；pì","description":"pì：传说中的一种野兽，似熊，一说似虎。\n〔～子〕即黄鼬”。\n〔～貅〕ａ．传说中的一种猛兽；ｂ．喻勇猛的军士或军队，如～～之士”。\n〔～虎〕喻勇士或勇猛的军队。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-貔"},{"id":"glyph-seal-8c98","script":"seal","character":"貘","reading":"mò","description":"mò：哺乳动物，体型类似犀。鼻长能自由伸缩，无角，生活在热带。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-貘"},{"id":"glyph-seal-8d1d","script":"seal","character":"贝","reading":"bèi","description":"牡蛎、蛤或其它软体动物中腹足类和瓣鳃类的统称。体软无节,外束膜一层曰外套膜,能分泌液质,结构成壳,名为介\n贝壳\n古代货币\n①软体动物的总称。特指有介壳的软体动物。如蚌、蛤蜊等。\n②古代用贝壳做的货币。\n③姓。\n【贝雕】用贝壳雕刻或镶嵌成的工艺品。\n【贝尔格莱德】南斯拉夫首都。也是塞尔维亚首府。位于东北部、萨瓦河同多瑙河交汇处。面积182平方公里。是全联邦的重要水、陆、空交通枢纽。\n【贝加尔湖】世界最深的湖泊。位于苏联东西伯利亚南部。平均深730米，最深达1620米。面积3.15万平方公里〓面海拔456米。淡水湖。水生动物种类繁多。\n【贝母】百合科多年生草本。叶条形，花被黄绿色，下垂钟形。鳞茎入药，有祛痰止咳作用。种类多。如四川的川贝母、东北的平贝母、新疆的伊贝母等。\n【贝宁雕塑】贝宁是西非的古国，位于今尼日利亚境内，有过高度的文明史。贝宁雕刻有铜塑和泥塑像。其作风写实而富有装饰性，造型洗练完美，显示出非洲黑人的高度智慧和艺术创造才能。\n【贝希斯顿铭文】波斯帝国国王大流士一世建立的记功石刻。用古波斯文、新埃兰文和巴比伦文3 种楔形文字刻在古都埃克巴坦那西南的贝希斯顿崖石上。是研究古波斯帝国历史的珍贵资料。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-贝"},{"id":"glyph-seal-8d1e","script":"seal","character":"贞","reading":"zhēn","description":"假借为正”、为定”。端方正直\n⒈坚定，有节操，有气节忠～。坚～不屈。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-贞"},{"id":"glyph-seal-8d1f","script":"seal","character":"负","reading":"fù","description":"⒈输，败，跟\"胜\"相对三胜二～。\n⒉背～粮。～荷。～载。～荆请罪。〈引〉担任～责尽职。～有重任。\n⒊遭受～屈。～轻伤。\n⒋仗恃，依靠～嵎顽抗。～险固守。\n⒌具有久～盛名。\n⒍违背，背弃～约。忘恩～义。\n⒎欠～债。\n⒏小于零的～数。\n⒐相对的两方面之反面，跟\"正\"相对～电。～极。\n【负气】赌气。\n【负疚】自己觉得惭愧不安。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-负"},{"id":"glyph-seal-8d21","script":"seal","character":"贡","reading":"gòng","description":"⒈〈古〉将物品进献给皇帝进～。\n⒉〈古〉进献给皇帝的物品～品。入～。\n⒊封建时代推荐、选举人才给朝廷～举。～生。～士。\n①将力量、知识、财物等献给国家和人民为祖国实现四个现代化，～献出自己的力量。\n②对人民、对人类所做的有益之事为人类作～献。伟大的～献。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-贡"},{"id":"glyph-seal-8d22","script":"seal","character":"财","reading":"cái","description":"苟粟多而财有余,\n财 金钱或物资～务、人～两空。\n【财帛】钱财。\n【财阀】以家族为中心、带有一定封建性的金融资本集团。以第二次世界大战前日本的最为典型。\n【财团】金融资本的组织形式。金融寡头所控制的大银行和大企业结合而成的垄断资本集团。\n【财政】国家对资财的收入与支出施行的管理～包干。\n【财政赤字】国家财政年度的支出超过收入的差额。这种差额，会计上习惯用红字表示，故称。又称预算赤字。\n【财政寡头】见【金融寡头】。\n【财政资本】见【金融资本】。\n财cái 1.金钱﹑物资的总称。 2.通\"材\"。原料;材料。 3.通\"才\"。资质，才能。 4.通\"裁\"。裁制;节制;裁断。 5.通\"纔\"。仅仅。 6.通\"纔\"。始，刚才。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-财"},{"id":"glyph-seal-8d23","script":"seal","character":"责","reading":"zé","description":"责一头。\n以塞官责。\n责备\n⒈分内应做的事～任。负～。尽职尽～。人人有～。\n⒊质问，诘问～问。\n⒋指摘斥～。谴～。\n⒌惩罚～罚。鞭～。杖～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-责"},{"id":"glyph-seal-8d24","script":"seal","character":"贤","reading":"xián","description":"有德行;多才能\n对人的敬称\n分明是如贤所教,但是小生自小坐书斋,不谙其他生活。╠\n⒈有道德、有才能的，也指德才兼备的人～明。选～与能。用人唯～。\n⒉胜过，甚于～于。\n⒊敬词。用于平辈或晚辈～妻。～甥。\n⒋〈古〉劳苦我从事独～。\n贤xiàn 1.车毂一端的大孔。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-贤"},{"id":"glyph-seal-8d25","script":"seal","character":"败","reading":"bài","description":"①失败残兵～将、成～在此一举。\n②打败大～敌军。\n④消除；解除～火。\n⑤破旧；腐烂；凋谢#草&开不#的鲜花。\n【败北】打败仗。\n【败笔】指写字写得不好的一笔。也指绘画中画得不好的部分或作文中写得不好～的词句。\n【败绩】指战争、事业等方面的失败。\n【败兴】正高兴时因遇到不希望发生的事而情绪低落；扫兴郊游时天下起了雨，真～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-败"},{"id":"glyph-seal-8d27","script":"seal","character":"货","reading":"huò","description":"财物,金钱珠玉布帛的总称\n患货之不足。\n⒈钱～币。通～。\n⒊商品～物充足。百～齐全。\n⒋卖～出。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-货"},{"id":"glyph-seal-8d28","script":"seal","character":"质","reading":"zhì","description":"援疑质理\n⒉朴实～朴。\n⒊抵押，抵押品典～。人～。\n⒋问，责问～疑。～问。\n⒌评判，核对而欲～天之有无。对～。\n①物理学上指物体所含物质的量。常用单位为克、公斤等。\n②指产品或工作的优劣程度产品～量。教学～量。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-质"},{"id":"glyph-seal-8d29","script":"seal","character":"贩","reading":"fàn","description":"古国名\n买货出售\n也单指买进货物\n比喻叛卖\n⒈指买货或买后再出卖～了一批货回来。～卖。\n⒉做买卖的行商或小商人小商～。摆摊～。鱼～子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-贩"},{"id":"glyph-seal-8d2a","script":"seal","character":"贪","reading":"tān","description":"贪婪。多欲而不知满足\n贪tān图财。原指贪财，后多指贪污。不知足的求取严惩～官。～赃枉法。～耍。～婪。～便宜。～心不足。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-贪"},{"id":"glyph-seal-8d2b","script":"seal","character":"贫","reading":"pín","description":"⒊言语噜苏，令人讨厌他耍～嘴。她那张嘴太～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-贫"},{"id":"glyph-seal-8d2c","script":"seal","character":"贬","reading":"biǎn","description":"降级\n特指降职并外放;贬谪\n其后\n②指出缺点，给予不好的评价，与'褒'相对有褒有～。\n【贬斥】\n①降低官级。\n②贬低并压制、排斥。\n【贬黜】降低或罢免官职。\n【贬低】有意降低对人或事物的评价。\n【贬义】言辞或字句里含有不赞成或坏的意思～词。\n【贬义词】含有厌恶、贬斥等感情色彩的词。\n【贬抑】贬低并压制。\n【贬责】指出过失、加以批评；责备横加～。\n【贬谪】封建时代指官吏降职，被派到边远地方做官。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-贬"},{"id":"glyph-seal-8d2d","script":"seal","character":"购","reading":"gòu","description":"原指用重金收买,后泛指买","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-购"},{"id":"glyph-seal-8d2e","script":"seal","character":"贮","reading":"zhù","description":"以广贮江宁、杭州、苏州之病梅\n贮zhù 1.储存;收藏。 2.指储存的财货。 3.盛，把东西放在器具里。 4.停放，安置。 5.唐时图籍副本之一。 6.通\"伫\"。等待。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-贮"},{"id":"glyph-seal-8d2f","script":"seal","character":"贯","reading":"guàn","description":"旧时用绳索穿钱,每一千文为一贯\n事情,事例\n⒉穿，穿连～穿。～串。连～。〈引〉通，连通～通。学～古今。融会～通。\n⒊原籍，出生地籍～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-贯"},{"id":"glyph-seal-8d30","script":"seal","character":"贰","reading":"èr","description":"二的大写\n① '二'的大写。\n②变节；背叛～臣。\n【贰臣】封建时代指在前一朝代做了官，投降后一朝代又做官的人。\n【贰心】见【二心】。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-贰"},{"id":"glyph-seal-8d31","script":"seal","character":"贱","reading":"jiàn","description":"地位低下,人格卑鄙\n鄙贱之人。\n其辱\n⒉地位低下，跟\"高贵\"相对卑～。贫～。\n⒊谦词～姓。～恙。\n⒋鄙视，轻视贵五谷而～金玉。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-贱"},{"id":"glyph-seal-8d32","script":"seal","character":"贲","reading":"bēn","description":"通奔”。急走;逃亡\n奔流\n今名膈膜或横隔膜,膈的古称\n虎贲勇士\n【贲临】敬辞。光临。\n贲fén 1.大。参见\"贲庸\"﹑\"贲鼓\"。 2.三足龟。参见\"贲j\"。 3.通\"坟\"。典籍;简策。 4.通\"獖\"。参见\"贲彘\"。\n贲bēn 1.通\"奔\"。奔走。 2.引申为勇。参见\"贲士\"。 3.通\"奔\"。星之一种，参见\"贲星\"。 4.横隔膜。\n贲fèn 1.通\"愤\"。怒气。 2.通\"坟\"。隆起。\n贲lù 1.见\"贲浑\"。\n贲pān 1.见\"贲禺\"。\n贲féi 1.姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-贲"},{"id":"glyph-seal-8d33","script":"seal","character":"贳","reading":"shì","description":"⒈赊～酒。\n⒉出赁，出借。\n⒊宽大，赦免～罪。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-贳"},{"id":"glyph-seal-8d34","script":"seal","character":"贴","reading":"tiē","description":"贴补。补偿,补益\n粘附;附着\n⒈粘附粘～。～年画。～对联。\n⒉挨近，紧靠～着河边游。～身汗衫。\n⒊补助～补。粮～。\n⒋恰当，适合，妥当～切。妥～。\n⒌依附，顺从服服～ ～。\n⒍量词。膏药一张 叫一～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-贴"},{"id":"glyph-seal-8d35","script":"seal","character":"贵","reading":"guì","description":"社会地位高\n一曰爵以\n⒈价钱高，跟\"贱\"相对米～。油～。〈引〉珍贵，宝贵最～者，人才也。\n⒉地位高或权势大，也指这类的人或集团显～。权～。达官～族。\n⒊重视，崇尚兵～神速。不～义，而～法。\n⒋敬词～姓？～宾。～公司。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-贵"},{"id":"glyph-seal-8d36","script":"seal","character":"贶","reading":"kuàng","description":"通况”。比方\n赐赠之物\n贶kuàng赐，赠送，赏赐～赠●～。嘉～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-贶"},{"id":"glyph-seal-8d37","script":"seal","character":"贷","reading":"dài","description":"借出钱财\n借入\n①借入或借出～款。\n②所贷的款农～。\n③推卸责无旁～。\n④宽恕严惩不～。\n【贷学金制度】高等院校给家庭经济困难的学生发放无息贷款，以保障他们正常的学习和生活的制度。\n贷tè 1.通\"忒\"。差错。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-贷"},{"id":"glyph-seal-8d38","script":"seal","character":"贸","reading":"mào","description":"改变\n古今一\n⒈交易，交换财物～易。抱布～丝。\n⒉轻率，冒冒失失～然前去。～ ～然来。\n贸móu 1.目眩。参见\"贸贸\"。 2.昏昧，昏庸。 3.通\"侔\"。等齐。 4.通\"牟\"。谋取。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-贸"},{"id":"glyph-seal-8d39","script":"seal","character":"费","reading":"fèi","description":"耗损\n⒈消耗，花掉～尽心机。花～太大。～劲。～时间。莫浪～。\n⒉费用，为某种需要所使用的款项军～。学～。旅～。电～。\n【费解】不好懂他说的这句话太～解。\n费fú 1.违背，不顺利。\n费bì 1.古地名。春秋鲁邑，在今山东省费县西北。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-费"},{"id":"glyph-seal-8d3a","script":"seal","character":"贺","reading":"hè","description":"奉送礼物表示庆祝\n是以贺。\n何贺之有。\n嘉奖;犒劳\n赞许;附和\n贺hè庆祝，祝颂，道喜庆～。祝～。恭～。～电。～新年。～功酒。～喜宴。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-贺"},{"id":"glyph-seal-8d3b","script":"seal","character":"贻","reading":"yí","description":"美人之贻。\n遗留\n⒈赠给，送给～人。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-贻"},{"id":"glyph-seal-8d3c","script":"seal","character":"贼","reading":"zéi","description":"⒈匪盗，偷东西的人盗～。窃～。\n⒉严重桅国家和人民的坏人乱臣～子。卖国～。\n⒊伤害戕～。\n⒋邪的，不正派～眉～眼。～头～脑。\n⒌对敌人的蔑称已破～。\n⒍〈方〉狡猾老鼠太～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-贼"},{"id":"glyph-seal-8d3e","script":"seal","character":"贾","reading":"jiǎ","description":"坐卖。泛指卖\n⒈〈古〉商人富商大～。又特指坐商。\n⒉做买卖善～。\n⒋求取～好。〈引〉招引，招惹～祸。\n⒌见jiǎ。\n⒈姓。\n⒉〈古〉通\"价\"。\n⒊见gǔ。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-贾"},{"id":"glyph-seal-8d3f","script":"seal","character":"贿","reading":"huì","description":"贿赂的财物\n赠送财物\n孟献子聘于周,王以为有礼\n⒈〈古〉财物货～。\n⒊用财物买通别人或指买通别人的财物被迫行～。索～受～，罪行累累。勤政廉洁，杜绝～赂。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-贿"},{"id":"glyph-seal-8d41","script":"seal","character":"赁","reading":"lìn","description":"租用、租借\n工钱,给受雇人的报酬\n⒈租，租借租～。出～。～房。\n⒉给人当雇工～佣。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-赁"},{"id":"glyph-seal-8d42","script":"seal","character":"赂","reading":"lù","description":"行贿,用钱、物买通别人\n⒈〈古〉指赠送财物。\n⒉财物。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-赂"},{"id":"glyph-seal-8d44","script":"seal","character":"资","reading":"zī","description":"⒊供给，凭借～助。仅～参考。可～借鉴。\n⒋条件，威望～格。～望。\n①用于发展国民经济的物资或货币。\n②本钱。\n资zì 1.逞情;放纵。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-资"},{"id":"glyph-seal-8d47","script":"seal","character":"赇","reading":"qiú","description":"行贿\n受贿\n非理而求;强求\n贿赂,用来买通别人的财物\n赇qiú贿赂受～枉法。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-赇"},{"id":"glyph-seal-8d48","script":"seal","character":"赈","reading":"zhèn","description":"救济～济。～灾。～捐。～恤。以工代～。放～。\n赈zhèn救济～救。～济。～灾。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-赈"},{"id":"glyph-seal-8d49","script":"seal","character":"赉","reading":"lài","description":"赠送\n⒈［癩病］即\"麻风病\"。\n⒉生癣疥等皮肤病，以致毛发脱落～皮狗。\n⒊表面凹凸不平或有斑点的～蛤蟆。～南瓜。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-赉"},{"id":"glyph-seal-8d4a","script":"seal","character":"赊","reading":"shē","description":"买货延期交款\n段注贳买者,在彼为贳,在我则为赊也。”\n卖物延期收款\n⒈买卖货物时欠着或延期付款～欠。～买。～销。\n⒉松，缓带～。\n⒊长，远蜀道～。\n⒋〈古〉通\"奢\"。奢侈。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-赊"},{"id":"glyph-seal-8d4b","script":"seal","character":"赋","reading":"fù","description":"缴纳赋税\n给予;授予\n⒉授予，给予～于。\n⒋念诗或作诗临清流而～诗。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-赋"},{"id":"glyph-seal-8d4c","script":"seal","character":"赌","reading":"dǔ","description":"泛指比胜负;争输赢\n①赌博。一种用财物作注争输赢的恶习。\n②泛指争输赢打～。\n【赌咒】发誓。\n【赌注】赌博时所押的钱财。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-赌"},{"id":"glyph-seal-8d4d","script":"seal","character":"赍","reading":"jī","description":"拿东西给人,送给\n携带;持\n⒈送东西给别人～粮。\n赍zī 1.费用﹔钱财。 2.材料;物资。 3.凭借;借助。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-赍"},{"id":"glyph-seal-8d4e","script":"seal","character":"赎","reading":"shú","description":"用财物脱罪或抵免过失\n⒈用财物换回人或抵押品～回。～当。\n⒉弥补，抵偿立功～罪。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-赎"},{"id":"glyph-seal-8d4f","script":"seal","character":"赏","reading":"shǎng","description":"玩赏;欣赏\n奇文共欣\n⒈赐，奖，给予～赐。奖～。～给。\n⒉奖赐的物品有～。受～。领～。\n⒊赞扬赞～。\n⒋喜爱，喜欢，领略趣味～花。～月。欣～。玩～。鉴～。观～。\n⒌敬词～光。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-赏"},{"id":"glyph-seal-8d50","script":"seal","character":"赐","reading":"cì","description":"给予;上给予下\n请给\n①赐予。～敬辞。指所受的礼物辱承厚～，受之有愧。\n【赐教】敬辞。给予指教承蒙～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-赐"},{"id":"glyph-seal-8d53","script":"seal","character":"赓","reading":"gēng","description":"酬答、应和\n通庚”。赔偿\n赓gēng继续～续不断。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-赓"},{"id":"glyph-seal-8d56","script":"seal","character":"赖","reading":"lài","description":"依靠;依赖;依恃、凭藉\n赖子存之。\n⒈倚靠，仗持依～。办好这件事，有～大家同心协力。\n⒉不承认～债。抵～。证据确凿，～是～不掉的。\n⒊诬陷，反过来怪人诬～。自己错了，别～他人。\n⒋怪罪，责备学习成绩差，只能～自己努力不够。\n⒌差，劣，坏这种电视机的质量不～。\n⒍停在某地，不愿离开～在家里。\n⒎［无赖］\n①生活无依无靠。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-赖"},{"id":"glyph-seal-8d58","script":"seal","character":"赘","reading":"zhuì","description":"聚会\n通缀”。连缀,附着\n⒉男子就婚女家～婿。入～。招～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-赘"},{"id":"glyph-seal-8d59","script":"seal","character":"赙","reading":"fù","description":"拿钱财帮助别人办理丧事\n赙 fù送财物帮助人办丧事。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-赙"},{"id":"glyph-seal-8d5b","script":"seal","character":"赛","reading":"sài","description":"比试\n⒈比较好坏、强弱、胜负比～。排球～。拔河～。\n⒉胜似，比得上一年～一年。能～过他。\n⒊旧时一种迷信活动，所谓\"酬报神灵\"而举行的祭典～神。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-赛"},{"id":"glyph-seal-8d5e","script":"seal","character":"赞","reading":"zàn","description":"导引\n辅佐,佐助\n赞帷幄之谋\n⒈辅佐，帮助～助。\n⒉称颂，夸奖～美。～扬。～许。称～。\n①同意。\n②支持，助人成功。\n①婚、丧、庆典、祭祀等仪式进行时，在旁宣诵行礼项目。\n②赞礼的人。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-赞"},{"id":"glyph-seal-8d60","script":"seal","character":"赠","reading":"zèng","description":"赠zèng送，无代价地送东西给别人～送。～阅。～言。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-赠"},{"id":"glyph-seal-8d61","script":"seal","character":"赡","reading":"shàn","description":"周济;帮助\n充满\n足;充足\n⒈富足，充足丰～。\n⒉供给～养。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-赡"},{"id":"glyph-seal-8d62","script":"seal","character":"赢","reading":"yíng","description":"宽缓;松懈\n大夫君\n⒈获利，利润～利。～余。\n⒉获得，得到～得。\n⒊胜，获胜打～了。\n⒋背，担～粮。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-赢"},{"id":"glyph-seal-8d63","script":"seal","character":"赣","reading":"gàn","description":"赣江,在江西省\n江西省的别称\n⒈江西省的简称。\n⒉赣江，在江西省。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-赣"},{"id":"glyph-seal-8d64","script":"seal","character":"赤","reading":"chì","description":"chì：(1)红色，比朱色稍暗的颜色～血。～字。\n(2)真诚，忠诚～诚（极其真诚）。～忱。～子（纯洁无暇的初生婴儿，古代亦指百姓）。～胆忠心。\n(3)空无所有～手空拳。～地千里。\n(4)裸露～脚（光脚）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-赤"},{"id":"glyph-seal-8d66","script":"seal","character":"赦","reading":"shè","description":"shè：免除和减轻刑罚～书。～令。～免。～恕。大～。特～。十恶不～。罪在不～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-赦"},{"id":"glyph-seal-8d67","script":"seal","character":"赧","reading":"nǎn","description":"nǎn：因羞惭而脸红～～。～然。～愧。～颜。～然汗下。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-赧"},{"id":"glyph-seal-8d6b","script":"seal","character":"赫","reading":"hè","description":"hè：(1)明显，显著，盛大显～。喧～。～奕。～烜。\n(2)发怒～咤。～怒。～然。\n(3)红如火烧，泛指红色～如渥赭”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-赫"},{"id":"glyph-seal-8d6d","script":"seal","character":"赭","reading":"zhě","description":"zhě：红褐色～石（矿物，土状赤铁矿，可做颜料）。～衣（古代罪人穿的赤褐色的衣服，借指罪人）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-赭"},{"id":"glyph-seal-8d70","script":"seal","character":"走","reading":"zǒu","description":"zǒu：(1)行～路。～步。\n(2)往来～亲戚。\n(3)移动～向（延伸的方向）。～笔（很快地写）。钟表不～了。\n(4)往来运送～信。～私。\n(5)离去～开。刚～。出～。\n(6)经过～账。～内线。～后门。\n(7)透漏出去，超越范围～气（漏气）。\n(8)失去原样～形。～样。\n(9)古代指奔跑～马。不胫而～。\n(10)仆人，我”的谦辞牛马～（当牛作马的仆人，如太史公～～～。”）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-走"},{"id":"glyph-seal-8d73","script":"seal","character":"赳","reading":"jiū","description":"jiū：〔～～〕雄壮威武的样子，如～～武夫”、雄～～，气昂昂”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-赳"},{"id":"glyph-seal-8d74","script":"seal","character":"赴","reading":"fù","description":"fù：(1)往，去～京。～会。～任。～约。～宴。\n(2)投入（某种境地），参加（某种行列）～战。～敌（加入对敌作战）。～难（nàn）。～义。\n(3)古同讣”，讣告。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-赴"},{"id":"glyph-seal-8d75","script":"seal","character":"赵","reading":"zhào","description":"字亦作踴”\n古国名\n周穆王封造父于赵,故址在今山西省赵城县西南\n战国七雄之一。在今山西北部、河北西部和南部一带\n赵王于是遂遣。\n赵diào 1.锄地铲草。 2.通\"掉\"。参见\"赵缭\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-赵"}];
